package com.lingdong.learning.student.application;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import org.springframework.context.annotation.*;import org.springframework.transaction.annotation.EnableTransactionManagement;import org.springframework.jdbc.datasource.*;import org.springframework.jdbc.core.JdbcTemplate;
import com.lingdong.learning.student.infrastructure.persistence.*;import com.lingdong.learning.student.domain.Student;import com.lingdong.learning.organization.infrastructure.persistence.OrganizationMapper;import com.lingdong.learning.organization.domain.Organization;import com.lingdong.learning.datascope.application.OrganizationDataScopeService;import com.lingdong.learning.feature.application.FeatureAccessService;import com.lingdong.learning.auth.application.AuthenticatedUser;import com.lingdong.learning.auth.domain.AuthClientType;import java.util.List;
class BatchClassConfigurationTest {
 static final AuthenticatedUser ACTOR=new AuthenticatedUser(1L,1L,"fixture","fixture",AuthClientType.MINIAPP,List.of());
 @Configuration @EnableTransactionManagement static class Config{
  @Bean javax.sql.DataSource dataSource(){return new DriverManagerDataSource("jdbc:h2:mem:batch_class_"+System.nanoTime()+";DB_CLOSE_DELAY=-1","sa","");}
  @Bean org.springframework.transaction.PlatformTransactionManager transactionManager(javax.sql.DataSource ds){return new DataSourceTransactionManager(ds);}
  @Bean JdbcTemplate jdbc(javax.sql.DataSource ds){return new JdbcTemplate(ds);}
  @Bean Fixture fixture(){return new Fixture();}
  @Bean BatchClassConfigurationService service(Fixture f){return new BatchClassConfigurationService(f.students,f.relations,f.organizations,f.access,f.scopes,f.features,f.lifecycle);}

 }
 static class Fixture {final StudentMapper students=mock(StudentMapper.class);final StudentOrganizationMapper relations=mock(StudentOrganizationMapper.class);final OrganizationMapper organizations=mock(OrganizationMapper.class);final StudentManagementAccessService access=mock(StudentManagementAccessService.class);final OrganizationDataScopeService scopes=mock(OrganizationDataScopeService.class);final FeatureAccessService features=mock(FeatureAccessService.class);final StudentOrganizationLifecycleService lifecycle=mock(StudentOrganizationLifecycleService.class);}
 AnnotationConfigApplicationContext context(){var c=new AnnotationConfigApplicationContext(Config.class);c.getBean(JdbcTemplate.class).execute("CREATE TABLE fixture_write(student_id BIGINT)");var orgs=c.getBean(Fixture.class).organizations;when(orgs.findById(21L)).thenReturn(Organization.create(21L,null,"ROOT","school","school","SCHOOL","/21/",1,null));for(long id:List.of(31L,32L))when(orgs.findById(id)).thenReturn(Organization.create(id,21L,"21","class"+id,"class","CLASS","/21/"+id+"/",1,null));when(c.getBean(Fixture.class).scopes.canAccess(1L,31L)).thenReturn(true);when(c.getBean(Fixture.class).scopes.canAccess(1L,32L)).thenReturn(true);var students=c.getBean(Fixture.class).students;when(students.findByIdForUpdate(anyLong())).thenAnswer(i->Student.create(i.getArgument(0),"fixture","G1",41L));var r=c.getBean(Fixture.class).relations;when(r.findActiveEnrollmentOrganizationIds(anyLong())).thenReturn(List.of(21L));when(r.findActiveClassOrganizationIdsInEnrollment(anyLong(),eq(21L))).thenReturn(List.of(31L));return c;}
 @Test void laterFailureRollsBackEarlierMemberAndLocksInStableOrder(){try(var c=context()){var jdbc=c.getBean(JdbcTemplate.class);var lifecycle=c.getBean(Fixture.class).lifecycle;when(lifecycle.transferClass(eq(ACTOR),anyLong(),any())).thenAnswer(i->{long student=i.getArgument(1);jdbc.update("INSERT INTO fixture_write VALUES(?)",student);if(student==12L)throw new IllegalStateException("fixture write failure");return null;});assertThrows(IllegalStateException.class,()->c.getBean(BatchClassConfigurationService.class).configure(ACTOR,31,32,List.of(12L,11L),"fixture reason"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM fixture_write",Integer.class));var order=inOrder(c.getBean(Fixture.class).students);order.verify(c.getBean(Fixture.class).students).findByIdForUpdate(11L);order.verify(c.getBean(Fixture.class).students).findByIdForUpdate(12L);}}
 @Test void staleSourceMembershipIsRejectedBeforeAnyChanges(){try(var c=context()){when(c.getBean(Fixture.class).relations.findActiveClassOrganizationIdsInEnrollment(12L,21L)).thenReturn(List.of(33L));assertThrows(IllegalStateException.class,()->c.getBean(BatchClassConfigurationService.class).configure(ACTOR,31,32,List.of(11L,12L),"fixture reason"));verifyNoInteractions(c.getBean(Fixture.class).lifecycle);}}
 @Test void validBatchDelegatesExistingDomainAndReturnsExactMembers(){try(var c=context()){var result=c.getBean(BatchClassConfigurationService.class).configure(ACTOR,31,32,List.of(12L,11L)," fixture reason ");assertEquals(List.of(11L,12L),result);verify(c.getBean(Fixture.class).lifecycle).transferClass(ACTOR,11L,new TransferStudentClassCommand(32L,"fixture reason"));verify(c.getBean(Fixture.class).lifecycle).transferClass(ACTOR,12L,new TransferStudentClassCommand(32L,"fixture reason"));}}
 @Test void explicitPermissionDenialStopsAllResourceReads(){try(var c=context()){var f=c.getBean(Fixture.class);doThrow(new com.lingdong.learning.common.security.SystemOperationAccessDeniedException("fixture denied")).when(f.access).require(ACTOR,"STUDENT_ORGANIZATION_MANAGE");clearInvocations(f.organizations,f.students);assertThrows(com.lingdong.learning.common.security.SystemOperationAccessDeniedException.class,()->c.getBean(BatchClassConfigurationService.class).configure(ACTOR,31,32,List.of(11L),"reason"));verifyNoInteractions(f.organizations,f.students,f.lifecycle);}}
 @Test void crossSchoolTargetIsRejectedBeforeMemberReads(){try(var c=context()){var f=c.getBean(Fixture.class);when(f.organizations.findById(23L)).thenReturn(Organization.create(23L,null,"ROOT","other","other","SCHOOL","/23/",1,null));when(f.organizations.findById(32L)).thenReturn(Organization.create(32L,23L,"23","other_class","class","CLASS","/23/32/",1,null));assertThrows(com.lingdong.learning.common.web.ResourceNotFoundException.class,()->c.getBean(BatchClassConfigurationService.class).configure(ACTOR,31,32,List.of(11L),"reason"));verifyNoInteractions(f.students,f.lifecycle);}}
 @Test void duplicateSelectionIsRejectedWithoutLocking(){try(var c=context()){var f=c.getBean(Fixture.class);assertThrows(IllegalArgumentException.class,()->c.getBean(BatchClassConfigurationService.class).configure(ACTOR,31,32,List.of(11L,11L),"reason"));verifyNoInteractions(f.students,f.lifecycle);}}
 @Test void trainingInstitutionReusesExistingAdditionalClassSemantics(){try(var c=context()){var f=c.getBean(Fixture.class);when(f.organizations.findById(21L)).thenReturn(Organization.create(21L,null,"ROOT","training","training","TRAINING_INSTITUTION","/21/",1,null));assertEquals(List.of(11L),c.getBean(BatchClassConfigurationService.class).configure(ACTOR,31,32,List.of(11L),"reason"));verify(f.lifecycle).transferClass(ACTOR,11L,new TransferStudentClassCommand(32L,"reason"));}}
}
